// Generates the home gallery's creatives (nine fictional brands, one format each, every one a different topic, look and
// motion idea) into site/compositions/gallery-*/: composition.json, meta.json and assets/*.svg. The gallery also shows
// three hero creatives (KOVA, TIDEFALL, Fernwise), generated by hero-gen. Posters are rendered separately (posters.mjs).
// Usage: node site/scripts/gallery-gen/build.mjs [outDir]
// Text widths come from hero-gen/widths.json; a text not measured yet is measured in Chrome first (needs node
// site/build.mjs), then everything is generated again with the real width.
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { MISSING, writeComposition } from '../hero-gen/lib.mjs';
import { osteria } from './osteria.mjs';
import { altavia } from './altavia.mjs';
import { volt } from './volt.mjs';
import { noir } from './noir.mjs';
import { ombra } from './ombra.mjs';
import { signal } from './signal.mjs';
import { form } from './form.mjs';
import { greenroots } from './greenroots.mjs';
import { nightsky } from './nightsky.mjs';

/** Each creative: `{ id, comp, meta, assets }`. */
export const CREATIVES = [osteria, altavia, volt, noir, ombra, signal, form, greenroots, nightsky];
export const DEFAULT_OUT = fileURLToPath(new URL('../../compositions', import.meta.url));

/** Writes every gallery composition under `out`; returns their ids and the texts whose width is not in widths.json yet. */
export function generate(out = DEFAULT_OUT) {
  MISSING.clear();
  const ids = [];
  for (const make of CREATIVES) {
    const { id, comp, meta, assets } = make();
    writeComposition(out, id, comp, meta, assets);
    ids.push(id);
  }
  return { ids, missing: [...MISSING] };
}

export const GALLERY_IDS = CREATIVES.map((make) => make().id);

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  const out = process.argv[2] ? join(process.cwd(), process.argv[2]) : DEFAULT_OUT;
  let { missing } = generate(out);
  if (missing.length) {
    const { measure } = await import('../hero-gen/measure.mjs');
    console.log(`measured ${await measure(missing)} new text widths`);
    ({ missing } = generate(out));
  }
  if (missing.length) { console.error(`unmeasured widths: ${missing.join(', ')}`); process.exit(1); }
  console.log(`gallery compositions written to ${out}`);
}
